/* Browser-native ES module. No CDN, runtime package download, or client-side secrets. */
const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => new Intl.NumberFormat('en-US', {style:'currency', currency:'USD',maximumFractionDigits:2}).format(v ?? 0);
const num = v => new Intl.NumberFormat('en-US', {maximumFractionDigits:2}).format(v ?? 0);
const pct = v => v == null ? 'Not available' : `${num(v)}%`;
const date = v => v ? new Date(v).toLocaleDateString('en-US', {month:'2-digit',day:'2-digit',year:'numeric',timeZone:'UTC'}) : 'Not yet';
const stamp = v => v ? new Date(v).toLocaleString('en-US', {month:'2-digit',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}) : 'Not yet';
const signed = v => `<span class="${v >= 0 ? 'positive':'negative'}">${money(v)}</span>`;
const pill = (s, tone = '') => `<span class="pill ${tone}">${esc(String(s).replaceAll('_',' '))}</span>`;
const button = (label, action, id = '', style = 'secondary small') => `<button type="button" class="${style}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const empty = (title, text, action = '') => `<div class="empty"><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;
const stat = (label, value, note = '') => `<div class="stat"><div class="stat-label">${label}<span>↗</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;
const panel = (title, sub, content, extra = '') => `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>${content}</section>`;
const kv = (k,v) => `<div class="key-value"><span>${k}</span><span>${v}</span></div>`;
const input = (label, name, value, type='number', attrs='') => `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select = (label, name, options, value) => `<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const table = (heads, rows) => `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const tabs = [['WORKSPACE','overview','◫','Command center'],['','scanner','⌕','Opportunity scanner'],['','research','⌘','Research lab'],['','strategies','◈','Strategy lab'],['','backtests','⌁','Backtesting studio'],['EXECUTION','builder','◇','Trade builder'],['','trading','⇄','Trading terminal'],['','portfolio','▥','Portfolio & risk'],['OPERATIONS','agents','⊞','Agent operations'],['','data','▤','Data & intelligence'],['','integrations','⊕','Integrations'],['','settings','⚙','Settings']];
const state = {o:null, tab:'overview', strategyId:'strategy-longshot-v1', datasetId:'synthetic-v1', run:null, markets:[], cursor:'', marketInfo:null, source:'kalshi', initialized:false, series:'', marketSearch:'', filters:{topic:'all',minVolume:'0',maxSpread:'100',minPrice:'0',maxPrice:'100',sort:'volume'}, draft:null, ticket:null, quote:null, comparison:[], waiting:null, busy:false};
let chatSession = sessionStorage.getItem('stonks-chat');
if(!chatSession){chatSession=crypto.randomUUID();sessionStorage.setItem('stonks-chat',chatSession);}
let toastTimer;
function toast(message, error=false){const e=$('#toast');e.textContent=message;e.className=error?'error':'';e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.hidden=true,error?13000:6000);}
async function api(path, body, method){
 const response=await fetch('/api'+path,{method:method||(body===undefined?'GET':'POST'),headers:{'Content-Type':'application/json','X-Stonks-Request':'1'},...(body===undefined?{}:{body:JSON.stringify(body)})});
 let result;try{result=await response.json();}catch{throw Error(`Server returned HTTP ${response.status}`);}
 if(!response.ok){if(response.status===401){$('#shell').hidden=true;$('#login').hidden=false;}throw Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail||result));}
 return result;
}
const currentStrategy=()=>state.o.strategies.find(s=>s.id===state.strategyId)||state.o.strategies[0];
const currentAccount=()=>state.o.accounts.find(a=>a.source===state.source);
const datasetOptions=()=>[...state.o.datasets].sort((a,b)=>(a.source==='synthetic')-(b.source==='synthetic')).map(d=>[d.id,d.source==='synthetic'?'Practice data (generated; NOT Kalshi)':`${d.name} [Historical ${d.source}]`]);
const realDatasets=()=>state.o.datasets.filter(d=>d.source!=='synthetic');
const selectedDataset=()=>state.o.datasets.find(d=>d.id===state.datasetId);
function workflowGuide(active=''){const steps=[['scanner','1. Discover','Find a real Kalshi market'],['data','2. Collect history','Import settled contracts'],['backtests','3. Backtest','Evaluate a defined strategy'],['research','4. Validate','Challenge the result'],['trading','5. Paper trade','Simulate current orders']];return `<section class="panel" aria-label="Research workflow"><div class="panel-head"><div><h2>How the pieces connect</h2><p>Real-time quotes and historical data are different. Move through these steps, or ask the copilot for help.</p></div></div><div class="guide-steps">${steps.map(([id,label,detail])=>`<button type="button" data-action="nav" data-id="${id}" class="guide-step ${id===active?'active':''}"><strong>${label}</strong><small>${detail}</small></button>`).join('')}</div></section>`;}
const strategyOptions=()=>state.o.strategies.map(s=>[s.id,`${s.config.name} · v${s.version}`]);
function head(eyebrow,title,description,action=''){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function sourceNotice(){return `<div class="notice ${state.source==='synthetic'?'':'info'}">${state.source==='synthetic'?'PRACTICE DATA ONLY: these are invented examples for learning the controls, NOT Kalshi markets or evidence of a trading edge.':'KALSHI SELECTED / PAPER CAPITAL: current exchange data appear only after a successful fetch. Orders remain simulated; no exchange orders are submitted.'}</div>`;}
function sourcePicker(){return select('Market-data source','source',[['kalshi','Real Kalshi markets (paper orders only)'],['synthetic','Practice examples (generated)']],state.source);}
function chart(run){
 if(!run?.equity_curve?.length)return empty('No performance series','Run a historical test to generate an equity curve.');
 const values=run.equity_curve, w=720,h=220,left=59,right=13,top=18,bottom=28, baseline=run.metrics.starting_capital;
 const lo=Math.min(baseline,...values.map(x=>x.equity)),hi=Math.max(baseline,...values.map(x=>x.equity));const padding=Math.max((hi-lo)*.18,20),min=lo-padding,max=hi+padding;
 const first=Date.parse(values[0].time),last=Date.parse(values.at(-1).time),timeSpan=Math.max(1,last-first);
 const x=t=>left+(Date.parse(t)-first)/timeSpan*(w-left-right),y=v=>top+(max-v)/(max-min)*(h-top-bottom);
 const points=values.map(v=>`${x(v.time).toFixed(1)},${y(v.equity).toFixed(1)}`).join(' ');
 const area=`M ${left},${h-bottom} L ${points.replaceAll(' ',' L ')} L ${w-right},${h-bottom} Z`;
 return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Actual calculated backtest equity curve"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c5f580" stop-opacity=".14"/><stop offset="100%" stop-color="#c5f580" stop-opacity="0"/></linearGradient></defs>${[0,.33,.66,1].map(f=>{const v=min+(max-min)*f;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-8}" y="${y(v)+3}" text-anchor="end">${num(v)}</text>`;}).join('')}<path class="area" d="${area}"/><line class="benchmark" x1="${left}" x2="${w-right}" y1="${y(baseline)}" y2="${y(baseline)}"/><polyline class="equity" points="${points}"/><text x="${left}" y="${h-5}">${date(values[0].time)}</text><text x="${w-right}" y="${h-5}" text-anchor="end">${date(values.at(-1).time)}</text></svg><div class="chart-caption"><span><i class="legend-dot"></i> Strategy equity · ${esc(run.source)}</span><span>Dashed: starting cash · UTC dates</span></div>`;
}
function runStats(run){const m=run.metrics;return (m.closed_trades===0?'<div class="notice">No trades qualified and settled under this strategy and dataset. $0 does NOT mean the strategy broke even. Check entry thresholds, data coverage and settlement dates.</div>':'')+`<div class="stats">${stat('Net P&L',signed(m.net_pnl),'After modeled entry fees')}${stat('Total return',pct(m.return_pct),`${m.closed_trades} closed trades`)}${stat('Maximum drawdown',pct(m.max_drawdown_pct),'Bid-marked equity, before exit fees')}${stat('Estimated fees',money(m.fees),`${m.independent_events} event IDs`)}</div>`;}
function runTable(){return table(['EXPERIMENT / SOURCE','RETURN','DRAWDOWN','TRADES','ACTIONS'],state.o.runs.map(r=>`<tr><td><strong>${esc(r.config.strategy.name)}</strong><small>${esc(r.dataset_name)} · ${date(r.created_at)}</small></td><td class="numeric ${r.metrics.net_pnl>=0?'positive':'negative'}">${pct(r.metrics.return_pct)}</td><td class="numeric">${pct(r.metrics.max_drawdown_pct)}</td><td class="numeric">${r.metrics.closed_trades}</td><td><div class="inline-actions">${button('Open','open-run',r.id)}${button(state.comparison.includes(r.id)?'Selected':'Compare','compare-run',r.id)}</div></td></tr>`));}
function jobTable(){return table(['JOB','STAGE / STATUS','CREATED','ACTION'],state.o.jobs.map(j=>`<tr><td><strong>${esc(j.job_type)}</strong><small>${esc(j.payload.question||j.payload.strategy?.name||j.payload.series||j.id)}</small></td><td>${pill(j.status,j.status==='failed'?'red':j.status==='completed'?'':'muted')}<small>${esc(j.stage)}</small></td><td>${stamp(j.created_at)}</td><td>${button('Inspect','job',j.id)} ${['queued','running'].includes(j.status)?button('Cancel','cancel-job',j.id):button('Rerun','retry-job',j.id)}</td></tr>`));}
function overview(){const o=state.o,a=currentAccount(),atRisk=a.positions.reduce((n,p)=>n+p.cost,0),jobs=o.jobs.filter(j=>['queued','running'].includes(j.status));return head('YOUR EDGE, UNDER EXAMINATION','Research first. Conviction second.','One workbench for discovering ideas, testing the evidence and putting strategies to work with paper capital.',button('New investigation <span>↗</span>','nav','research','primary'))+workflowGuide()+sourceNotice()+`<div class="stats">${stat('Paper cash',money(a.cash),`${state.source==='synthetic'?'Sandbox':'Kalshi-data'} account · no real funds`)}${stat('Capital at risk',money(atRisk),`${a.positions.length} open positions, at cost`)}${stat('Research experiments',num(o.runs.length),'Saved runs, not validated strategies')}${stat('Research queue',num(jobs.length),`${o.jobs.filter(j=>j.status==='completed').length} completed jobs`)}</div><div class="two-col">${panel('Evidence over intuition','Latest selected historical experiment',chart(state.run),pill(state.run?.source||'NO DATA','amber'))}${panel('Your research pipeline','Actual saved work, end to end',`<div class="workflow"><div><span>01 / DEFINE</span><strong>${o.strategies.length}</strong><small>Strategy versions</small></div><div><span>02 / TEST</span><strong>${o.runs.length}</strong><small>Historical runs</small></div><div><span>03 / CHALLENGE</span><strong>${o.research.length}</strong><small>Validation reports</small></div><div><span>04 / OBSERVE</span><strong>${o.deployments.filter(d=>d.enabled).length}</strong><small>Paper deployments</small></div></div><p style="font-size:10px;margin:18px 0 0">A promising backtest is a research lead, not a green light. Every stage retains its data and assumptions.</p>`)}</div><div class="equal-col">${panel('Recent investigations','No fabricated agent activity',o.jobs.length?o.jobs.slice(0,4).map(j=>`<div class="feed-item"><span class="feed-icon">${j.status==='completed'?'✓':'⌁'}</span><div><h3>${esc(j.payload.question||j.payload.strategy?.name||j.job_type)}</h3><p>${esc(j.stage)} · ${esc(j.status)}</p><time>${stamp(j.created_at)}</time></div></div>`).join(''):empty('Your desk is ready','Start an investigation or enable a bounded research schedule.',button('Open research lab','nav','research')))}${panel('Start with a question','Your next experiment',`<div class="feed-item"><span class="feed-icon">01</span><div><h3>Are longshots overpriced?</h3><p>Test the counterparty strategy by price band, category and holding horizon.</p></div></div><div class="feed-item"><span class="feed-icon">02</span><div><h3>Does your forecast beat the quote?</h3><p>Import independent, timestamped probabilities. Test only what was known then.</p></div></div><div class="form-actions">${button('Build a strategy','nav','strategies','primary small')}${button('Connect evidence','nav','data')}</div>`)}</div>`;}
function strategyEditor(){const s=state.draft||currentStrategy().config;return `<form id="strategy-form"><div class="notice info"><strong>What this tests:</strong> ${s.family==='longshot'?'Whether buying NO against low-priced YES outcomes historically made money. This is a screening hypothesis, not a forecast of fair value.':'Whether independently estimated, time-stamped probabilities predicted outcomes better than executable market quotes. You must import historical model data.'}</div><div class="form-grid">${input('Research hypothesis name','name',s.name,'text','required maxlength="100"')}${select('Research method','family',[['longshot','Test the pricing of unlikely outcomes'],['model_edge','Compare independent forecasts to market prices']],s.family)}${select('Position to simulate','side',[['no','Buy NO'],['yes','Buy YES']],s.side)}${select('Market focus','category',[['All','All categories'],['Weather','Weather'],['Sports','Sports'],['Economics','Economics'],['Politics','Politics'],['Unclassified','Unclassified']],s.category)}</div><details class="advanced-strategy"><summary>Advanced strategy and risk settings (optional)</summary><p>These parameters define the exact historical experiment. Prices are fractions of $1 (0.10 means 10¢). Leave defaults unless you want to test a specific threshold.</p><div class="form-grid">${input('Minimum YES ask (0–1)','min_probability',s.min_probability,'number','step=".01" min="0" max="1"')}${input('Maximum YES ask (0–1)','max_probability',s.max_probability,'number','step=".01" min="0" max="1"')}${input('Minimum independent model edge (0–1)','min_edge',s.min_edge,'number','step=".01" min="0" max="1"')}${input('Minimum observed volume','min_volume',s.min_volume,'number','min="0"')}${input('Position budget fraction','risk_fraction',s.risk_fraction,'number','step=".0001" min=".0001" max=".1"')}${input('Event exposure cap fraction','event_cap',s.event_cap,'number','step=".001" min=".001" max=".25"')}${input('Portfolio cap fraction','total_cap',s.total_cap,'number','step=".01" min=".01" max="1"')}${select('Position sizing','sizing',[['fixed_fraction','Fixed fraction of starting capital'],['quarter_kelly','Quarter Kelly (model-edge only)']],s.sizing)}</div></details><div class="form-actions"><button class="primary" type="submit">Save research strategy ↗</button>${button('Inspect exact rules','preview-strategy')}</div></form>`;}
function strategies(){return head('STRATEGY LAB','Start with a research idea.','Ask the research desk to propose a testable strategy, or select a starting hypothesis. You can inspect and change every rule before saving.')+workflowGuide('research')+panel('Let the research desk do the setup','No programming or numerical configuration needed to begin.',`<div class="equal-col"><div class="strategy-card"><h3>Are unlikely outcomes overpriced?</h3><p>Study buying NO against low-priced YES contracts. Price alone does not prove overpricing; the hypothesis needs historical calibration and realistic NO execution prices.</p>${button('Prepare this strategy','preset-longshot','','primary small')}</div><div class="strategy-card"><h3>Does an independent forecast beat the market?</h3><p>Compare time-stamped model probabilities with market quotes. Requires external forecasts and historical evidence, which the app cannot generate from market prices alone.</p>${button('Prepare this strategy','preset-model','','primary small')}</div></div><div class="form-actions">${button('Ask AI to propose a strategy','ask-strategy','','primary small')}${button('Explore markets first','nav','scanner')}</div>`)+`<div class="two-col">${panel(state.draft?'Copilot / imported draft':'Strategy rules','Hold-to-settlement entry templates. Values are fractions, not percentages.',strategyEditor())}${panel('Strategy library','Native, user-authored and manifest strategies share the same engine',`<div style="display:grid;gap:12px">${state.o.strategies.map(s=>`<div class="strategy-card ${s.id===state.strategyId?'active':''}"><div>${pill(s.config.family,'muted')} ${pill('v'+s.version)}</div><h3>${esc(s.config.name)}</h3><p>${esc(s.config.side.toUpperCase())} · ${esc(s.config.category)} · YES ask ${pct(s.config.min_probability*100)}–${pct(s.config.max_probability*100)}<br>Origin: ${esc(s.origin)}. Status: research, not approved for live trading.</p><div class="inline-actions">${button('Review / edit','edit-strategy',s.id)}${button('Have desk validate','validate-strategy',s.id,'primary small')}${button('Backtest manually','test-strategy',s.id)}${button('Paper deploy','deploy-strategy',s.id)}</div></div>`).join('')}</div>`)}</div>`;}
function research(){return head('RESEARCH LAB','Turn an idea into evidence.','Launch a chronological training, validation and held-out test, then challenge the result with higher costs.')+`<div class="notice info">${state.o.capabilities.agent_llm?"The optional model-backed Director translates your question into a constrained plan; a separate reviewer critiques the computed evidence. The plan and all changes are logged.":"Research questions label the selected strategy test. This release evaluates two explicit strategy families. Use the copilot or Strategy Lab to turn a different idea into supported rules before running it."}</div><div class="two-col">${panel('Commission an investigation','No code required. Every experiment is saved.',`<form id="research-form"><div class="form-grid">${select('Strategy','strategy_id',strategyOptions(),state.strategyId)}${select('Historical dataset','dataset_id',datasetOptions(),state.datasetId)}<label class="span-all">Research question<textarea name="question" rows="5" minlength="5" maxlength="2000" required placeholder="Does buying NO against low-probability contracts survive fees and an untouched test period?">Does this strategy retain positive net returns after out-of-sample and execution-cost stress testing?</textarea></label></div><div class="form-actions"><button class="primary" type="submit">Launch investigation ↗</button>${button('Review strategy rules','nav','strategies')}</div></form>`)}${panel('What actually happens','A bounded, reproducible research workflow',`<div class="timeline"><div><strong>Director & scout</strong><p>Validate dataset coverage and split events chronologically. Purge overlapping settlement horizons.</p></div><div><strong>Quantitative analyst</strong><p>Compare predefined candidates using training data only, then lock the winning configuration.</p></div><div><strong>Independent validator</strong><p>Evaluate holdout results, event-cluster uncertainty, sample size, and doubled fees/slippage.</p></div><div><strong>Risk review</strong><p>Save the evidence and limitations. No automatic live approval or capital allocation.</p></div></div>`)}</div>${panel('Research findings','Rejected ideas are retained, not hidden',state.o.research.length?table(['INVESTIGATION','SOURCE','STATUS','REVIEW'],state.o.research.map(r=>`<tr><td><strong>${esc(r.question)}</strong><small>${r.trials} candidates · ${r.purged_events} purged events</small></td><td>${pill(r.source,'amber')}</td><td>${pill(r.status,r.status==='not_validated'?'red':'amber')}</td><td>${button('Evidence','research-report',r.id)}</td></tr>`)):empty('No investigations yet','Run the form above to produce a real validation report.'))}`;}
function backtests(){const r=state.run;return head('BACKTESTING STUDIO','Test a strategy against history.','Choose a strategy, select historical observations, run a simulation, then inspect the trades and assumptions.')+workflowGuide('backtests')+(realDatasets().length===0?`<div class="notice info"><strong>No real Kalshi history has been imported.</strong> The practice dataset is generated for learning the controls. To test a real strategy, import settled Kalshi contracts first. ${button('Import Kalshi history','nav','data','primary small')}</div>`:'')+(selectedDataset()?.source==='synthetic'?'<div class="notice">Practice-data mode: results are NOT historical Kalshi performance. Select an imported Kalshi dataset for real research.</div>':'')+panel('Configure an experiment','Dates are UTC. Positions still open at the end are marked, not magically settled.',`<form id="backtest-form"><div class="form-grid three">${select('Strategy','strategy_id',strategyOptions(),state.strategyId)}${select('Dataset','dataset_id',datasetOptions(),state.datasetId)}${input('Starting capital ($)','capital',10000,'number','min="100" max="10000000" required')}${input('Start date (optional, UTC)','start','','date')}${input('End date (optional, UTC)','end','','date')}${input('Fee coefficient (estimate)','fee_coefficient',.07,'number','min="0" max="1" step=".005"')}${input('Adverse slippage ($ / contract)','slippage',.005,'number','min="0" max=".1" step=".001"')}${input('Bar-volume participation cap','participation',.05,'number','min=".001" max="1" step=".001"')}</div><div class="form-actions"><button class="primary" type="submit">Run backtest ↗</button><small>Only settled historical contracts can produce completed-trade results. Historical data are imported in Data & intelligence.</small></div></form>`)+(r?runStats(r)+panel('Experiment equity',`${esc(r.config.strategy.name)} · ${esc(r.dataset_name)}`,chart(r),pill(r.source,'amber'))+panel('Read before interpreting','The engine reports limitations alongside returns.',`<details><summary>Assumptions, warnings and reproducibility</summary>${r.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}<pre>${esc(JSON.stringify({engine:r.engine_version,dataset_hash:r.dataset_hash,configuration:r.config},null,2))}</pre></details><div class="inline-actions"><a href="/api/export/${encodeURIComponent(r.id)}?format=csv">Export trades CSV ↗</a><a href="/api/export/${encodeURIComponent(r.id)}">Export full run JSON ↗</a></div>${table(['CONTRACT / ENTRY','SIDE','QUANTITY','ENTRY','FEES','NET P&L'],r.trades.slice(-100).reverse().map(t=>`<tr><td><strong>${esc(t.ticker)}</strong><small>${stamp(t.entered_at)} · ${esc(t.category)}</small></td><td>${esc(t.side.toUpperCase())}</td><td class="numeric">${t.quantity}</td><td class="numeric">${money(t.price)}</td><td class="numeric">${money(t.fee)}</td><td class="numeric">${signed(t.pnl)}</td></tr>`))}<small>Showing the last ${Math.min(100,r.trades.length)} closed trades. Full history is in the export.</small>`):'')+panel('Experiment history','Select two runs to compare. Keep different datasets and assumptions visible.',runTable(),button('Compare selected ('+state.comparison.length+')','show-comparison'))}
function inferredTopic(m){const text=(m.title+' '+m.ticker).toLowerCase();if(m.category&&m.category!=='Unclassified'&&m.category!=='Other')return m.category;for(const [topic,pattern] of [['Sports',/football|basketball|baseball|hockey|soccer|tennis|golf|touchdown|goal|nfl|nba|mlb|nhl|match|spurs|lions/],['Weather',/temperature|rainfall|snowfall|weather|degrees|hurricane|wind speed/],['Politics',/election|senate|president|governor|congress|midterm|democrat|republican/],['Economics',/inflation|unemployment|gdp|interest rate|fed rate|cpi|jobs report/],['Finance',/bitcoin|crypto|nasdaq|stock price|ethereum|oil price/]])if(pattern.test(text))return topic;return 'Other';}
function filteredMarkets(){const f=state.filters,q=state.marketSearch.toLowerCase().trim();return state.markets.filter(m=>{const price=m.yes_ask==null?null:m.yes_ask*100,spread=m.yes_ask!=null&&m.yes_bid!=null?(m.yes_ask-m.yes_bid)*100:null;return (!q||(m.title+' '+m.ticker+' '+m.category).toLowerCase().includes(q))&&(f.topic==='all'||inferredTopic(m)===f.topic)&&(price===null?(Number(f.minPrice)===0&&Number(f.maxPrice)===100):(price>=Number(f.minPrice)&&price<=Number(f.maxPrice)))&&Number(m.volume||0)>=Number(f.minVolume)&&(spread===null?Number(f.maxSpread)===100:spread<=Number(f.maxSpread));}).sort((a,b)=>f.sort==='price'?(a.yes_ask??1)-(b.yes_ask??1):f.sort==='spread'?((a.yes_ask??1)-(a.yes_bid??0))-((b.yes_ask??1)-(b.yes_bid??0)):Number(b.volume||0)-Number(a.volume||0));}
function marketRows(){return filteredMarkets().map(m=>`<tr><td><strong>${esc(m.title)}</strong><small>${esc(m.ticker)} · ${esc(inferredTopic(m))}${m.category==='Unclassified'?' (topic inferred)':''}</small></td><td class="numeric">${m.yes_bid==null?'—':pct(m.yes_bid*100)}</td><td class="numeric">${m.yes_ask==null?'—':pct(m.yes_ask*100)}</td><td class="numeric">${num(m.volume)}</td><td>${m.yes_ask!=null&&m.yes_ask<=.15?pill('Low-priced YES','amber'):pill('Unassessed','muted')}</td><td>${button('Inspect','market',m.ticker)} ${state.source==='kalshi'?button('Ask copilot','investigate-market',m.ticker):''} ${button('Paper ticket','ticket',m.ticker,'primary small')}</td></tr>`);}
function scanner(){return head('OPPORTUNITY SCANNER','Discover real markets.','Browse currently open Kalshi contracts. A low price is a research lead, not proof of an edge.')+workflowGuide('scanner')+sourceNotice()+panel('Market universe','Select an explicit source. API failures never fall back to sample data.',`<form id="market-form" class="toolbar">${sourcePicker()}${input('Kalshi series ticker (optional)','series',state.series,'text','placeholder="e.g. a verified series ticker"')}<button type="submit" class="primary">Load markets ↗</button></form><div class="notice info"><strong>Research-first discovery:</strong> Filter the markets we have actually fetched, or ask the copilot to investigate a theme. A low-priced YES is not necessarily mispriced. ${button('Ask AI to investigate','ask-discover','','primary small')}</div><div class="form-grid three" id="market-filters">${select('Topic (may be inferred)','topic',[['all','All topics'],['Sports','Sports'],['Politics','Politics'],['Weather','Weather'],['Economics','Economics'],['Finance','Finance'],['Other','Other']],state.filters.topic)}${select('Minimum volume','minVolume',[[0,'Any volume'],[10,'10+'],[100,'100+'],[1000,'1,000+']],state.filters.minVolume)}${select('Maximum bid-ask spread','maxSpread',[[100,'Any spread'],[5,'5 percentage points'],[10,'10 percentage points'],[20,'20 percentage points']],state.filters.maxSpread)}${select('Minimum YES ask','minPrice',[[0,'Any'],[5,'5¢'],[10,'10¢'],[25,'25¢'],[50,'50¢']],state.filters.minPrice)}${select('Maximum YES ask','maxPrice',[[100,'Any'],[5,'5¢'],[10,'10¢'],[25,'25¢'],[50,'50¢'],[75,'75¢']],state.filters.maxPrice)}${select('Sort by','sort',[['volume','Highest volume'],['price','Lowest YES ask'],['spread','Narrowest spread']],state.filters.sort)}</div><div class="form-actions">${button('Clear filters','clear-market-filters')}</div><label>Search loaded markets<input id="market-search" type="search" placeholder="Filter markets already loaded (not exchange-wide)…" value="${esc(state.marketSearch)}"></label><p id="market-count">${filteredMarkets().length} matching markets among ${state.markets.length} fetched. Filters apply only to fetched pages, not the whole exchange.</p><div id="market-table">${state.markets.length?table(['MARKET','YES BID','YES ASK','VOLUME','SCREEN','ACTION'],marketRows()):empty('Choose your market universe','Load current Kalshi markets or choose practice examples.')}</div><div class="form-actions">${state.cursor?button('Load next page','more-markets'):''}<small>${esc(state.marketInfo?.coverage||'Only the returned page is shown. This is not an exhaustive exchange search.')} ${state.marketInfo?`Updated ${stamp(state.marketInfo.fetched_at)}`:''}</small></div>`)}
function builder(){const t=state.ticket||{ticker:state.source==='synthetic'?'DEMO-1':'',side:'no',quantity:10,limit_price:.92},q=state.quote;return head('TRADE BUILDER','Review a market and prepare a paper order.','Start in the market scanner, select a contract, review its actual rules and quote, then submit a simulated order.')+workflowGuide('trading')+sourceNotice()+`<div class="two-col">${panel('Single-contract paper ticket','Buy-only, immediate-or-cancel simulation. Held until settlement.',`<form id="ticket-form"><div class="form-grid">${sourcePicker()}${input('Exact market ticker','ticker',t.ticker,'text','required pattern="[A-Z0-9.\\-]{1,160}"')}${select('Side','side',[['yes','Buy YES'],['no','Buy NO']],t.side)}${input('Contracts','quantity',t.quantity,'number','min="1" max="10000" required')}${input('Maximum price ($ / contract)','limit_price',t.limit_price,'number','min=".0001" max=".9999" step=".0001" required')}<div><label>Maximum payout</label><div id="ticket-payout" class="stat-value">${money(t.quantity)}</div></div></div><div class="notice info" style="margin-top:18px">A fresh order book is fetched again at submission. Partial fills and zero fills are possible. This is not a reservation or guaranteed execution.</div><label><input type="checkbox" name="confirm" required>I authorize this PAPER order. No real funds.</label><div class="form-actions"><button class="primary" type="submit">Submit paper order ↗</button>${button('Refresh quote','refresh-quote')}</div></form>`)}${panel('Market evidence','Read the exact rules. The model does not define settlement.',q?`${kv('Instrument',esc(q.market.ticker))}${kv('Status',esc(q.market.status))}${kv('Supported binary contract',q.market.binary_supported?'Yes':'No, execution blocked')}${kv('Book received',stamp(q.book.received_at))}${kv('Best YES ask',q.book.yes.length?money(q.book.yes[0][0]):'No depth')}${kv('Best NO ask',q.book.no.length?money(q.book.no[0][0]):'No depth')}<details open><summary>Settlement rules</summary><p>${esc(q.market.rules)}</p></details>`:empty('No quote loaded','Refresh the quote or select a market in the scanner.',button('Open scanner','nav','scanner')))}</div>${panel('Combination research','Probability bounds, not an exchange-supported combo order.',`<div class="notice">Native Kalshi combo quotation/execution is not implemented. Separate orders are not a native combo. This calculator uses your assumptions and must not be read as a forecast.</div><form id="combo-form" class="toolbar"><label>Assumed leg probabilities, comma separated<input name="probabilities" value="0.60, 0.65, 0.55" required></label><button type="submit" class="secondary">Analyze dependence</button></form><div id="combo-result"></div>`)}`;}
function trading(){const a=currentAccount();return head('TRADING TERMINAL','Monitor paper trades and strategies.','Orders here are simulated. Individual trades come from Trade Builder; approved strategies can also run paper-only scans.')+workflowGuide('trading')+sourceNotice()+`<div class="toolbar">${sourcePicker()}${button(a.halted?'Resume paper trading':'Pause all new paper orders','halt',String(!a.halted),a.halted?'primary':'danger')}${button('Reconcile settlements','reconcile')}</div><div class="stats">${stat('Available cash',money(a.cash),'Simulated account')}${stat('Realized P&L',signed(a.realized_pnl),'Only reconciled settlements')}${stat('Entry fees',money(a.fees),'Estimated, not exchange charges')}${stat('Status',a.halted?'Paused':'Ready',`${a.positions.length} open positions`)}</div>${panel('Open positions','Buy-and-hold positions. No hidden or assumed liquidation.',a.positions.length?table(['CONTRACT','SIDE','QUANTITY','TOTAL COST','MAX PAYOUT','ENTERED'],a.positions.map(p=>`<tr><td><strong>${esc(p.title)}</strong><small>${esc(p.ticker)} · ${esc(p.event_id)}</small></td><td>${esc(p.side.toUpperCase())}</td><td>${p.quantity}</td><td>${money(p.cost)}</td><td>${money(p.quantity)}</td><td>${stamp(p.entered_at)}</td></tr>`)):empty('No open positions','Create a paper ticket or activate a forward strategy.',button('Build trade','nav','builder')))}${panel('Forward strategy deployments','At most one order per deployment/contract. Bounded page scan about once per minute.',`<form id="deploy-form"><div class="form-grid">${select('Saved longshot strategy','strategy_id',strategyOptions(),state.strategyId)}${input('Kalshi series (blank = one open-market page)','series',state.series,'text')}<label class="span-all"><input type="checkbox" name="confirm" required>I authorize automatic PAPER orders in the ${esc(state.source)} account within fixed account risk limits.</label></div><div class="form-actions"><button class="primary" type="submit">Activate paper strategy ↗</button></div></form><div style="margin-top:20px">${state.o.deployments.length?table(['STRATEGY','SOURCE','LAST SCAN','STATE','ACTION'],state.o.deployments.map(d=>`<tr><td><strong>${esc(d.strategy.name)}</strong><small>${esc(d.error||d.coverage||'Waiting for first scheduled scan')}</small></td><td>${esc(d.source)}</td><td>${stamp(d.last_scan)}</td><td>${pill(d.enabled?'active':'paused',d.error?'red':'')}</td><td>${button(d.enabled?'Pause':'Resume','toggle-deployment',d.id)}</td></tr>`)):''}</div>`)}${panel('Order ledger','IOC remainders are canceled. Duplicate order IDs cannot double-charge the account.',state.o.orders.filter(o=>o.source===state.source).length?table(['ORDER / TIME','SIDE','REQUESTED / FILLED','COST','STATE'],state.o.orders.filter(o=>o.source===state.source).map(o=>`<tr><td><strong>${esc(o.ticker)}</strong><small>${stamp(o.executed_at)}</small></td><td>${esc(o.side.toUpperCase())}</td><td>${o.quantity} / ${o.filled_quantity}</td><td>${money(o.cost)}</td><td>${pill(o.status,o.status==='unfilled'?'amber':'')}</td></tr>`)):empty('No order activity','Submitted paper orders will appear here.'))}${state.source==='synthetic'?panel('Sandbox settlement test','Explicitly resolve a fictional instrument to exercise cash and P&L reconciliation.',`<form id="sandbox-form" class="toolbar">${select('Synthetic ticker','ticker',[1,2,3,4,5,6].map(n=>['DEMO-'+n,'DEMO-'+n]),'DEMO-1')}${select('Assumed outcome','outcome',[['yes','YES'],['no','NO']],'no')}<button type="submit">Resolve synthetic market</button></form>`):''}`;}
function portfolio(){const a=currentAccount(),cost=a.positions.reduce((sum,p)=>sum+p.cost,0),events={};a.positions.forEach(p=>events[p.event_id]=(events[p.event_id]||0)+p.cost);return head('PORTFOLIO & RISK','Know what can go wrong.','Risk is measured at contract, event and account levels. Event IDs do not capture every economic correlation.')+sourceNotice()+`<div class="toolbar">${sourcePicker()}</div><div class="stats">${stat('Cash + position cost',money(a.cash+cost),'Cost basis, NOT market-value equity')}${stat('Maximum position loss',money(cost),'All open premiums and entry fees')}${stat('Realized P&L',signed(a.realized_pnl),'No assumed unrealized gains')}${stat('Distinct event IDs',Object.keys(events).length,'Not necessarily independent risks')}</div><div class="equal-col">${panel('Hard account controls','The paper engine enforces these independently of the copilot.',`${kv('Per-contract maximum',pct(a.limits.contract_fraction*100)+' of initial capital')}${kv('Per-event maximum',pct(a.limits.event_fraction*100)+' of initial capital')}${kv('Total exposure cap',pct(a.limits.total_fraction*100)+' of initial capital')}${kv('Committed / permitted',money(cost)+' / '+money(a.initial_capital*a.limits.total_fraction))}<div class="risk-bar"><div style="width:${Math.min(100,100*cost/(a.initial_capital*a.limits.total_fraction))}%"></div></div><p>All exposure includes estimated entry fees. A pause blocks new orders; it does not close already-filled positions.</p>`)}${panel('Event concentration','Shared teams, weather systems or releases may add hidden dependence.',Object.keys(events).length?Object.entries(events).map(([k,v])=>`${kv(esc(k),money(v))}<div class="risk-bar"><div style="width:${Math.min(100,100*v/(a.initial_capital*a.limits.event_fraction))}%"></div></div>`).join(''):empty('No event exposure','Positions will be grouped by their exchange event IDs.'))}</div>${panel('Settlements','Recorded cash releases, not estimated wins.',state.o.settlements.filter(s=>s.source===state.source).length?table(['CONTRACT','PAYOUT','COST','P&L','RECONCILED'],state.o.settlements.filter(s=>s.source===state.source).map(s=>`<tr><td>${esc(s.ticker)}</td><td>${money(s.payout)}</td><td>${money(s.cost)}</td><td>${signed(s.pnl)}</td><td>${stamp(s.reconciled_at)}</td></tr>`)):empty('No settlements yet','Reconcile positions in the trading terminal when markets finalize.'))}`;}
function agents(){const roles=[['Director','Plans bounded jobs and partitions evidence.'],['Scout','Checks universe coverage and time validity.'],['Quant Analyst','Runs actual numerical experiments.'],['Validator','Challenges costs, sample size and holdout results.'],['Risk Review','Records limitations without live promotion.'],['Data Collector','Imports requested market observations.']];return head('AGENT OPERATIONS','A research desk you can inspect.','Structured role handoffs and actual job events. The math and risk gates are deterministic. Model-backed planning and critique are available when explicitly configured.')+`<div class="three-col">${roles.map(([name,description])=>{const active=state.o.jobs.find(j=>j.status==='running'&&j.stage===name);return `<div class="agent-card">${pill(active?'Working':'Idle',active?'':'muted')}<h3>${name}</h3><p>${description}</p><small>${active?esc(active.id.slice(0,8)):'Invoked as needed, not a continuous chatbot'}</small></div>`;}).join('')}</div><div style="height:18px"></div>${panel('Autonomous research schedule','Reevaluates a changed selected dataset within a daily job budget. Does not scrape or invent new datasets.',`<form id="schedule-form"><div class="form-grid three">${select('Dataset','dataset_id',datasetOptions(),state.o.schedule.dataset_id)}${input('Minimum interval (minutes)','interval_minutes',state.o.schedule.interval_minutes,'number','min="15" max="1440"')}${input('Maximum jobs / day','max_jobs_daily',state.o.schedule.max_jobs_daily,'number','min="1" max="96"')}</div><div class="form-actions"><label><input type="checkbox" name="enabled" ${state.o.schedule.enabled?'checked':''}>Enable autonomous dataset review</label><button type="submit" class="primary small">Save schedule</button></div><small>${esc(state.o.schedule.last_action||'No scheduled review yet.')} Last checked: ${stamp(state.o.schedule.last_checked)}</small></form>`)}${panel('Research queue & activity','Cancel is cooperative at a checkpoint; completed effects are not rolled back.',state.o.jobs.length?jobTable():empty('The queue is clear','Launch an investigation, run a backtest, or import historical data.'))}`;}
function dataPage(){return head('DATA & INTELLIGENCE','Collect historical evidence.','The market scanner shows live quotes. Backtests require settled contracts and their past price observations.')+workflowGuide('data')+`<div class="notice info"><strong>To backtest real Kalshi contracts:</strong> identify a series and settled market tickers, enter a historical date range below, and import. Once the job completes, its dataset will be selected automatically in Backtesting Studio. Open markets cannot supply final settlement outcomes.</div><div class="three-col"><div class="strategy-card">${pill('On-demand adapter')}<h3>Kalshi</h3><p>Market discovery, current books and live/archive candles. Credentials may be required by an endpoint.</p></div><div class="strategy-card">${pill('On-demand adapter')}<h3>National Weather Service</h3><p>Current forecast context. Not archived forecasts or a calibrated settlement probability.</p></div><div class="strategy-card">${pill('Not implemented','muted')}<h3>Sports / economic feeds</h3><p>Bring timestamped evidence through dataset import. Provider-specific live models remain an extension.</p></div></div><div style="height:18px"></div>${panel('Dataset registry','Downloads include warnings and source attribution.',table(['DATASET','SOURCE','ROWS / CONTRACTS','COVERAGE','ACTIONS'],state.o.datasets.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.description||'')}</small></td><td>${pill(d.source,'amber')}</td><td>${num(d.row_count)} / ${num(d.coverage?.contracts)}</td><td>${date(d.coverage?.start)}<br>${date(d.coverage?.end)}</td><td>${button('Inspect','dataset',d.id)} ${button('Use in backtest','use-dataset',d.id)} <a href="/api/export/${encodeURIComponent(d.id)}">JSON ↗</a></td></tr>`)))}<div class="equal-col">${panel('Import your observations','JSON object with rows, or a CSV using the observation schema.',`<form id="upload-form"><div class="form-grid">${input('Dataset name','name','','text','required maxlength="160"')}<label>File (.json or .csv)<input name="file" type="file" accept=".json,.csv" required></label><label class="span-all">Source / provenance<textarea name="provenance" rows="3" minlength="5" required placeholder="Provider, collection method, point-in-time availability and known gaps…"></textarea></label><label class="span-all"><input type="checkbox" name="synthetic">These are synthetic/generated observations</label></div><div class="form-actions"><button class="primary" type="submit">Validate & import</button><a href="/api/export/synthetic-v1?format=csv">Download schema example ↗</a></div></form><details><summary>Required columns and conventions</summary><p>ticker, event_id, observed_at, available_at, yes_bid, yes_ask, volume, outcome, settled_at. Timestamps require timezone offsets. Prices use dollars from 0 to 1. Optional: category, quote_size, model_probability, model_asof. The last two must appear together.</p></details>`)}${panel('Import Kalshi history','Bounded import: up to 20 settled binary tickers and 365 days.',`<form id="import-form"><div class="form-grid">${input('Exact series ticker','series','','text','required placeholder="Verified series ticker"')}${select('Candle interval','interval',[[60,'Hourly'],[1440,'Daily']],60)}<label class="span-all">Exact settled market tickers<textarea name="tickers" rows="3" required placeholder="Separate tickers with commas or new lines"></textarea></label>${input('Start (UTC)','start','','date','required')}${input('End (UTC)','end','','date','required')}</div><div class="form-actions"><button class="primary" type="submit">Queue historical import</button></div><small>Partial coverage and rejected rows are reported. No claim of complete historical depth.</small></form>`)}</div>${panel('Weather research context','Enter the contract location, not your personal location. Example: Phoenix airport.',`<form id="weather-form" class="toolbar">${input('Latitude','latitude',33.43,'number','step=".0001" min="-90" max="90"')}${input('Longitude','longitude',-112.01,'number','step=".0001" min="-180" max="180"')}<button type="submit" class="secondary">Fetch NWS forecast</button></form><div id="weather-result"></div>`)}`;}
function integrations(){return head('INTEGRATIONS','Borrow the tooling. Test the claims.','Inspect external repositories and import declarative strategies. Untrusted code never receives keys or execution rights.')+`<div class="equal-col">${panel('Repository intake','Metadata inspection, not an audit or automatic installation.',`<form id="repo-form"><label>GitHub owner/repository<input name="repository" required pattern="[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+" placeholder="owner/repository"></label><div class="form-actions"><button class="primary" type="submit">Inspect repository ↗</button></div></form><p style="margin:18px 0 0;font-size:11px">Pins the current commit and records the reported license. Code, dependencies, data rights and backtest assumptions still need review. Private repositories require a server-side read token.</p>`)}${panel('Declarative strategy adapter','Supported families: longshot and model_edge. No arbitrary Python execution.',`<form id="manifest-form"><label>Strategy configuration JSON<textarea name="config" rows="9" spellcheck="false" required>${esc(JSON.stringify({name:'Imported longshot hypothesis',family:'longshot',side:'no',min_probability:.02,max_probability:.10},null,2))}</textarea></label><div class="form-actions"><button class="primary" type="submit">Review in Strategy Lab</button></div></form>`)}</div>${panel('Repository review queue','A review record never means the code has been approved.',state.o.integrations.length?table(['REPOSITORY','LICENSE','PINNED COMMIT','STATUS'],state.o.integrations.map(i=>`<tr><td><strong>${esc(i.repository)}</strong><small>${esc(i.description)}</small></td><td>${esc(i.license)}</td><td><code>${esc(i.pinned_commit.slice(0,12))}</code></td><td>${pill(i.status,'amber')}</td></tr>`)):empty('No repositories inspected','Add a repository to create a version-pinned intake record.'))}`;}
function settings(){const c=state.o.capabilities;return head('SETTINGS & DEPLOYMENT','Clear boundaries. No hidden permissions.','Server-side credentials stay out of the browser. Research autonomy and real-money authority are separate.')+`<div class="equal-col">${panel('Runtime capabilities','Configuration is not proof of successful upstream connectivity.',`${kv('Application','By Order of Stonks / '+esc(state.o.version))}${kv('Market-data environment',esc(c.kalshi_environment))}${kv('Kalshi key configured',c.kalshi_credentials_configured?'Yes':'No; public endpoints may still work')}${kv('LLM key configured',c.copilot?'Yes':'No; local assistant mode')}${kv('Copilot model',esc(c.model))}${kv('Model-backed research roles',c.agent_llm?'Enabled; Director and Validator':'Disabled; deterministic workflow')}${kv('Real-money orders','Not implemented; blocked server-side')}${kv('Native combo orders','Not implemented')}${kv('Worker heartbeat',stamp(state.o.worker_heartbeat))}`)}${panel('Railway deployment checklist','The repository includes Docker and Railway configuration.',`<p>Deploy this feature branch as one Railway service. Set <code>APP_ENV=production</code>, a unique <code>APP_PASSWORD</code> of at least 16 characters, and a random <code>SESSION_SECRET</code> of at least 32 characters.</p><p>Mount a persistent volume at <code>/app/data</code>, or attach PostgreSQL and set <code>DATABASE_URL</code>. Keep exactly one replica and one Uvicorn worker.</p><p>For model-assisted conversation, set <code>OPENAI_API_KEY</code>, <code>OPENAI_MODEL</code>, and optionally <code>OPENAI_MAX_CALLS_PER_DAY</code>. No key is required for the synthetic research workflow.</p><p>The health endpoint is <code>/healthz</code>. Production startup refuses missing authentication configuration.</p>`)}</div>${panel('Operational audit','Recent actual application events.',state.o.audit.length?table(['ACTION','TIME','DETAIL'],state.o.audit.map(e=>`<tr><td>${esc(e.action)}</td><td>${stamp(e.created_at)}</td><td><small>${esc(JSON.stringify(e.detail))}</small></td></tr>`)):empty('No audited changes yet','Saved strategies, copilot tools and paper orders will be recorded.'))}`;}
const pages={overview,scanner,research,strategies,backtests,builder,trading,portfolio,agents,data:dataPage,integrations,settings};
function render(){if(!state.o)return;const tab=tabs.find(t=>t[1]===state.tab)||tabs[0];$('#crumb').textContent=tab[3];$('#copilot-context').textContent=tab[3];$('#copilot-status').textContent=state.o.capabilities.copilot?'Model configured · bounded tools':'Local mode · model key not configured';$('#navigation').innerHTML=tabs.map(([section,id,icon,label])=>`${section?`<div class="nav-heading">${section}</div>`:''}<button class="nav-item ${state.tab===id?'active':''}" data-action="nav" data-id="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');$('#main').innerHTML=(pages[state.tab]||overview)();$('#heartbeat').textContent='Worker · '+stamp(state.o.worker_heartbeat);}
function navigate(tab){state.tab=pages[tab]?tab:'overview';history.replaceState(null,'','#'+state.tab);document.body.classList.remove('nav-open');render();window.scrollTo(0,0);}
async function refresh(renderNow=true){state.o=await api('/overview');if(!state.initialized){const imported=state.o.datasets.find(d=>d.source!=='synthetic');if(imported)state.datasetId=imported.id;state.initialized=true;}if(!state.run&&state.o.runs.length)state.run=await api('/records/'+state.o.runs[0].id);if(state.waiting){const job=state.o.jobs.find(j=>j.id===state.waiting);if(job?.status==='completed'){state.waiting=null;if(job.job_type==='backtest'){state.run=await api('/records/'+job.result_id);state.tab='backtests';toast('Backtest completed. Results are calculated and saved.');}else if(job.job_type==='import'){state.datasetId=job.result_id;state.tab='backtests';toast('Historical dataset imported and selected. Choose a strategy to test.');}else toast('Job completed. Open its evidence in Agent Operations.');renderNow=true;}else if(job?.status==='failed'){state.waiting=null;toast(job.error,true);renderNow=true;}}
 if(renderNow)render();else $('#heartbeat').textContent='Worker · '+stamp(state.o.worker_heartbeat);}
function formValues(form){return Object.fromEntries(new FormData(form).entries());}
function readStrategy(form){const x=formValues(form);for(const k of ['min_probability','max_probability','min_edge','min_volume','risk_fraction','event_cap','total_cap'])x[k]=Number(x[k]);return x;}
function dialog(title,content){$('#dialog-body').innerHTML=`<p class="eyebrow">EVIDENCE RECORD</p><h2>${esc(title)}</h2>${content}`;$('#detail-dialog').showModal();}
async function loadMarkets(more=false){const r=await api(`/markets?source=${state.source}&series=${encodeURIComponent(state.series)}&cursor=${encodeURIComponent(more?state.cursor:'')}`);state.markets=more?[...new Map([...state.markets,...r.markets].map(m=>[m.ticker,m])).values()]:r.markets;state.cursor=r.cursor;state.marketInfo=r;render();}
async function selectTicket(ticker){state.ticket={ticker,side:'no',quantity:10,limit_price:.99};state.quote=await api(`/quote/${encodeURIComponent(ticker)}?source=${state.source}`);const asks=state.quote.book.no;state.ticket.limit_price=asks.length?asks[0][0]:.99;state.ticket.client_order_id=crypto.randomUUID();navigate('builder');}
async function doAction(action,id,el){
 if(action==='nav'){navigate(id);return;}
 if(action==='open-run'){state.run=await api('/records/'+id);state.datasetId=state.run.config.dataset_id;if(state.run.config.strategy_id)state.strategyId=state.run.config.strategy_id;navigate('backtests');}
 if(action==='ask-strategy'){document.body.classList.remove('copilot-closed');await sendChat('Propose a researchable prediction-market strategy using the supported longshot or independent-model edge family. Explain the economic hypothesis, evidence required, limitations, and how to validate it. Prepare an inspectable strategy draft for review. Do not claim an edge from price alone.');}
 if(action==='preset-longshot'){state.draft={...currentStrategy().config,name:'Test whether unlikely YES outcomes are overpriced',family:'longshot',side:'no',category:'All',min_probability:.02,max_probability:.15,sizing:'fixed_fraction'};navigate('strategies');toast('Hypothesis prepared. Review rules below, then save and backtest.');}
 if(action==='preset-model'){state.draft={...currentStrategy().config,name:'Independent probability vs market price',family:'model_edge',side:'yes',category:'All',min_probability:0,max_probability:1,sizing:'fixed_fraction'};navigate('strategies');toast('Draft prepared. Real testing requires historical, time-stamped model probabilities.');}
 if(action==='edit-strategy'){state.strategyId=id;state.draft=null;navigate('strategies');}
 if(action==='validate-strategy'){const strategy=state.o.strategies.find(x=>x.id===id);const dataset=realDatasets().find(x=>x.id===state.datasetId)||realDatasets()[0];if(!dataset){navigate('data');toast('A historical Kalshi dataset is required. Import settled contracts before asking agents to validate a strategy.',true);return;}state.strategyId=id;state.datasetId=dataset.id;const job=await api('/research',{question:'Evaluate the '+strategy.config.name+' hypothesis on imported historical evidence, using chronological holdout validation and execution-cost stress tests.',strategy:strategy.config,dataset_id:dataset.id});state.waiting=job.id;await refresh(false);navigate('agents');toast('Research desk started a validation job. Follow the evidence here.');}
 if(action==='test-strategy'){state.strategyId=id;state.draft=null;navigate('backtests');}
 if(action==='deploy-strategy'){state.strategyId=id;navigate('trading');}
 if(action==='preview-strategy')dialog('Strategy rules',`<pre>${esc(JSON.stringify(readStrategy($('#strategy-form')),null,2))}</pre>`);
 if(action==='compare-run'){state.comparison=state.comparison.includes(id)?state.comparison.filter(v=>v!==id):[...state.comparison.slice(-1),id];render();}
 if(action==='show-comparison'){if(state.comparison.length!==2)throw Error('Select exactly two experiments first.');const runs=await Promise.all(state.comparison.map(i=>api('/records/'+i)));dialog('Experiment comparison',`<div class="notice">These runs are only directly comparable when their datasets, dates, capital and execution assumptions match.</div>${table(['MEASURE',...runs.map(r=>esc(r.config.strategy.name))],['source','dataset_hash'].map(k=>`<tr><td>${k}</td>${runs.map(r=>`<td><small>${esc(r[k])}</small></td>`).join('')}</tr>`).concat(['net_pnl','return_pct','max_drawdown_pct','closed_trades','fees'].map(k=>`<tr><td>${k}</td>${runs.map(r=>`<td>${num(r.metrics[k])}</td>`).join('')}</tr>`)))}<details><summary>All configuration differences</summary><pre>${esc(JSON.stringify(runs.map(r=>r.config),null,2))}</pre></details>`);}
 if(action==='job'){const j=await api('/records/'+id);dialog(j.job_type+' / '+j.status,`${j.error?`<div class="notice error">${esc(j.error)}</div>`:''}<div class="timeline">${j.events.map(e=>`<div><strong>${esc(e.role)}</strong><p>${esc(e.message)}</p><small>${stamp(e.at)} · ${esc(e.execution||'deterministic')}</small></div>`).join('')||'<p>No events yet.</p>'}</div>${j.result_id?button('Open result',j.job_type==='backtest'?'open-run':j.job_type==='research'?'research-report':'dataset',j.result_id,'primary'):''}<details><summary>Stored job payload</summary><pre>${esc(JSON.stringify(j.payload,null,2))}</pre></details>`);}
 if(action==='research-report'){const r=await api('/records/'+id);dialog(r.question,`${pill(r.status,r.status==='not_validated'?'red':'amber')}<div class="check-list">${r.checks.map(c=>`<div class="${c.passed?'positive':'negative'}">${c.passed?'✓':'×'} ${esc(c.name)}</div>`).join('')}</div>${table(['PARTITION','P&L','RETURN','EVENT IDs'],Object.entries(r.partitions).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${signed(v.net_pnl)}</td><td>${pct(v.return_pct)}</td><td>${v.independent_events}</td></tr>`))}<p>${r.limitations.map(esc).join('<br>')}</p>${r.qualitative_review?`<h3>Separate model critique</h3><p>${esc(r.qualitative_review.summary)}</p><pre>${esc(JSON.stringify(r.qualitative_review,null,2))}</pre>`:''}${button('Open held-out backtest','open-run',r.run_id,'primary')}`);}
 if(action==='dataset'){const d=await api('/records/'+id);dialog(d.name,`${pill(d.source,'amber')}<p>${esc(d.description||'')}</p><pre>${esc(JSON.stringify({...d,rows:d.rows.slice(0,3)},null,2))}</pre><small>Preview: first three rows. Download the record for all observations.</small>`);}
 if(action==='cancel-job'){await api('/jobs/'+id+'/cancel',{});await refresh();toast('Job cancellation recorded. Running calculations stop at the next checkpoint.');}
 if(action==='retry-job'){const j=await api('/jobs/'+id+'/retry',{});state.waiting=j.id;await refresh();toast('New job queued. Original evidence is preserved.');}
 if(action==='more-markets')await loadMarkets(true);
 if(action==='clear-market-filters'){state.filters={topic:'all',minVolume:'0',maxSpread:'100',minPrice:'0',maxPrice:'100',sort:'volume'};state.marketSearch='';render();}
 if(action==='ask-discover'){document.body.classList.remove('copilot-closed');await sendChat('Investigate potentially interesting current Kalshi markets across topics. Use actual market data, report exact search coverage, suggest testable hypotheses, and distinguish low-priced contracts from verified mispricings. Do not invent probabilities or claim an edge without validation.');}
 if(action==='use-dataset'){state.datasetId=id;navigate('backtests');toast('Dataset selected for your next backtest.');}
 if(action==='investigate-market'){const m=state.markets.find(m=>m.ticker===id);if(!m)throw Error('Market not loaded');document.body.classList.remove('copilot-closed');await sendChat(`Investigate Kalshi market ${m.ticker}: ${m.title}. Use actual market details and current data. Explain the rules, what evidence we have, and what additional historical data would be needed to backtest a strategy. Do not invent fair-value probabilities.`);}
 if(action==='market'){const m=state.markets.find(m=>m.ticker===id);dialog(m.title,`${kv('Ticker',esc(m.ticker))}${kv('Source',esc(m.source))}${kv('Last observed',stamp(m.observed_at))}${kv('Close time',stamp(m.close_time))}<p>${esc(m.rules)}</p>${button('Build paper ticket','ticket',m.ticker,'primary')}`);}
 if(action==='ticket'){if($('#detail-dialog').open)$('#detail-dialog').close();await selectTicket(id);}
 if(action==='refresh-quote'){const f=formValues($('#ticket-form'));state.source=f.source;state.ticket={...f,quantity:Number(f.quantity),limit_price:Number(f.limit_price),client_order_id:state.ticket?.client_order_id||crypto.randomUUID()};state.quote=await api(`/quote/${encodeURIComponent(f.ticker)}?source=${state.source}`);render();toast('Fresh quote loaded. Submission fetches another fresh book.');}
 if(action==='halt'){await api('/paper/'+state.source+'/halt',{enabled:id==='true'});await refresh();toast(id==='true'?'New paper submissions are paused. Existing positions remain open.':'Paper submissions resumed.');}
 if(action==='reconcile'){const r=await api('/paper/'+state.source+'/reconcile',{});await refresh();toast(`${r.settled} positions settled. ${r.errors.length} lookup errors.`,r.errors.length>0);}
 if(action==='toggle-deployment'){const d=state.o.deployments.find(d=>d.id===id);await api('/deployments/'+id,{enabled:!d.enabled});await refresh();}
}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;el.disabled=true;try{if($('#detail-dialog').open&&['open-run'].includes(el.dataset.action))$('#detail-dialog').close();await doAction(el.dataset.action,el.dataset.id,el);}catch(error){toast(error.message,true);}finally{el.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.closest('#market-filters')){state.filters[e.target.name]=e.target.value;render();return;}if(e.target.name==='source'&&['trading','portfolio'].includes(state.tab)){state.source=e.target.value;state.markets=[];state.quote=null;state.ticket=null;render();}});
document.addEventListener('input',e=>{if(e.target.id==='market-search'){state.marketSearch=e.target.value;$('#market-table').innerHTML=table(['MARKET','YES BID','YES ASK','VOLUME','SCREEN','ACTION'],marketRows());$('#market-count').textContent=filteredMarkets().length+' matching markets among '+state.markets.length+' fetched. Filters apply only to fetched pages.';}if(e.target.closest('#ticket-form')){if(state.ticket)state.ticket.client_order_id=crypto.randomUUID();if(e.target.name==='quantity')$('#ticket-payout').textContent=money(Number(e.target.value));}});
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.length))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed CSV quote');if(cell||row.length){row.push(cell);rows.push(row);}const headers=rows.shift().map(x=>x.replace(/^\uFEFF/,'').trim());return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??'']).filter(([h,v])=>v!==''||!['quote_size','model_probability','model_asof'].includes(h)).map(([h,v])=>[h,['yes_bid','yes_ask','volume','quote_size','model_probability'].includes(h)?Number(v):v])));}
document.addEventListener('submit',async e=>{
 const form=e.target;if(['chat-form','login-form'].includes(form.id))return;e.preventDefault();const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
 try{const f=formValues(form);
 if(form.id==='strategy-form'){const r=await api('/strategies',{config:readStrategy(form),parent_id:state.draft?null:state.strategyId,origin:state.draft?'reviewed_draft':'user'});state.strategyId=r.id;state.draft=null;await refresh();toast('New immutable strategy version saved.');}
 if(form.id==='backtest-form'){state.strategyId=f.strategy_id;state.datasetId=f.dataset_id;const payload={strategy_id:f.strategy_id,strategy:currentStrategy().config,dataset_id:f.dataset_id,capital:Number(f.capital),fee_coefficient:Number(f.fee_coefficient),slippage:Number(f.slippage),participation:Number(f.participation)};if(f.start)payload.start=f.start+'T00:00:00Z';if(f.end)payload.end=f.end+'T23:59:59Z';const j=await api('/backtests',payload);state.waiting=j.id;toast('Backtest queued. The result will open when the calculation completes.');await refresh(false);}
 if(form.id==='research-form'){state.strategyId=f.strategy_id;state.datasetId=f.dataset_id;const j=await api('/research',{question:f.question,strategy:currentStrategy().config,dataset_id:f.dataset_id});state.waiting=j.id;await refresh(false);navigate('agents');toast('Investigation queued. Every stage is recorded here.');}
 if(form.id==='market-form'){state.source=f.source;state.series=f.series.trim().toUpperCase();state.quote=null;state.ticket=null;await loadMarkets();}
 if(form.id==='ticket-form'){state.source=f.source;state.ticket={ticker:f.ticker,side:f.side,quantity:Number(f.quantity),limit_price:Number(f.limit_price),client_order_id:state.ticket?.client_order_id||crypto.randomUUID()};const r=await api('/paper/orders',{...state.ticket,source:f.source,confirm:f.confirm==='on'});state.ticket.client_order_id=crypto.randomUUID();await refresh(false);navigate('trading');toast(`PAPER ${r.status}: ${r.filled_quantity}/${r.quantity} contracts, ${money(r.cost)} modeled cost.`);}
 if(form.id==='deploy-form'){await api('/deployments',{strategy_id:f.strategy_id,source:state.source,series:f.series.trim().toUpperCase(),confirm:f.confirm==='on'});await refresh();toast('Paper-only deployment activated. First scan runs on the worker schedule.');}
 if(form.id==='sandbox-form'){const r=await api('/paper/sandbox-settle',{ticker:f.ticker,outcome:f.outcome});await refresh();toast(`${r.settled} synthetic position(s) reconciled. No real outcome was asserted.`);}
 if(form.id==='schedule-form'){await api('/schedule',{enabled:f.enabled==='on',dataset_id:f.dataset_id,interval_minutes:Number(f.interval_minutes),max_jobs_daily:Number(f.max_jobs_daily)});await refresh();toast('Research schedule saved.');}
 if(form.id==='upload-form'){const file=form.querySelector('[name=file]').files[0];if(file.size>24_000_000)throw Error('File exceeds the 24 MB upload limit.');const text=await file.text();const parsed=file.name.toLowerCase().endsWith('.csv')?parseCSV(text):JSON.parse(text);const rows=Array.isArray(parsed)?parsed:parsed.rows;await api('/datasets',{name:f.name,rows,provenance:f.provenance,synthetic:f.synthetic==='on'});await refresh();toast('Dataset validated and stored.');}
 if(form.id==='import-form'){const j=await api('/import/kalshi',{series:f.series.trim().toUpperCase(),tickers:f.tickers.split(/[\s,]+/).filter(Boolean),start:f.start+'T00:00:00Z',end:f.end+'T23:59:59Z',interval:Number(f.interval)});state.waiting=j.id;await refresh(false);navigate('agents');toast('Historical import queued. Coverage errors are retained.');}
 if(form.id==='weather-form'){const r=await api(`/weather?latitude=${Number(f.latitude)}&longitude=${Number(f.longitude)}`);$('#weather-result').innerHTML=`<div class="notice">${esc(r.warning)}</div><p>Issued ${stamp(r.issued_at)} · retrieved ${stamp(r.retrieved_at)} · <a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">NWS source ↗</a></p>${table(['PERIOD','TEMPERATURE','FORECAST'],r.periods.slice(0,8).map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.temperature)}°${esc(p.temperatureUnit)}</td><td>${esc(p.shortForecast)}</td></tr>`))}`;}
 if(form.id==='repo-form'){await api('/integrations/inspect',{repository:f.repository.trim()});await refresh();toast('Repository metadata saved. Code remains untrusted and uninstalled.');}
 if(form.id==='manifest-form'){const config=JSON.parse(f.config);state.draft={...currentStrategy().config,...config};navigate('strategies');toast('Manifest loaded for review. Saving validates the schema.');}
 if(form.id==='combo-form'){const probabilities=f.probabilities.split(',').map(v=>Number(v.trim()));const r=await api('/combo/analyze',{probabilities});$('#combo-result').innerHTML=`<div class="stats">${stat('Joint lower bound',pct(r.lower_bound*100),'No independence assumption')}${stat('Joint upper bound',pct(r.upper_bound*100),'No independence assumption')}${stat('Independence scenario',pct(r.independence_scenario*100),'Not a calibrated probability')}</div><p>${esc(r.warning)}</p>`;}
 }catch(error){toast(error.message,true);}finally{if(submit)submit.disabled=false;}
});
function appendMessage(role,text){if(role==='user')$('#copilot-welcome')?.remove();const node=document.createElement('div');node.className='message '+role;node.textContent=text;$('#messages').append(node);$('#messages').scrollTop=$('#messages').scrollHeight;return node;}
async function sendChat(message){const send=$('#send-chat');send.disabled=true;appendMessage('user',message);const answer=appendMessage('assistant','Working with the available research tools…');try{const r=await api('/copilot',{message,context:{tab:state.tab,strategy_id:state.strategyId,dataset_id:state.datasetId,run_id:state.run?.id||'',source:state.source,ticker:state.ticket?.ticker||''},session_id:chatSession});answer.textContent=r.text;for(const action of r.actions||[]){const b=document.createElement('button');b.className='secondary small';b.textContent=action.action==='navigate'?action.label:action.action==='strategy_draft'?'Review strategy draft':'Review paper ticket';b.addEventListener('click',()=>{if(action.action==='navigate')navigate(action.tab);if(action.action==='strategy_draft'){state.draft=action.config;navigate('strategies');}if(action.action==='trade_draft'){state.source=action.ticket.source;state.ticket={...action.ticket,client_order_id:crypto.randomUUID()};state.quote=action.quote;navigate('builder');}});answer.append(document.createElement('br'),b);}if(r.tools?.length){const d=document.createElement('details');const summary=document.createElement('summary');summary.textContent=`${r.tools.length} tool action(s) · inspect evidence`;const pre=document.createElement('pre');pre.textContent=JSON.stringify(r.tools,null,2);d.append(summary,pre);answer.append(d);}await refresh(false);}catch(error){answer.textContent=error.message;answer.classList.add('negative');}finally{send.disabled=false;$('#messages').scrollTop=$('#messages').scrollHeight;}}
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();const message=$('#chat-input').value.trim();if(message){$('#chat-input').value='';sendChat(message);}});
$$('[data-prompt]').forEach(b=>b.addEventListener('click',()=>sendChat(b.dataset.prompt)));
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/login',{password:formValues(e.target).password});e.target.reset();await start();}catch(error){$('#login-error').textContent=error.message;}});
$('#logout').addEventListener('click',async()=>{try{await api('/logout',{});location.reload();}catch(error){toast(error.message,true);}});
$('#refresh').addEventListener('click',()=>refresh().catch(e=>toast(e.message,true)));
$('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());
$('#menu').addEventListener('click',()=>document.body.classList.toggle('nav-open'));
$('#close-copilot').addEventListener('click',()=>{document.body.classList.add('copilot-closed');document.body.classList.remove('copilot-mobile-open');});
$('#toggle-copilot').addEventListener('click',()=>{document.body.classList.remove('copilot-closed');document.body.classList.toggle('copilot-mobile-open');});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
async function start(){const session=await api('/session');$('#login').hidden=session.authenticated;$('#shell').hidden=!session.authenticated;if(!session.authenticated)return;state.tab=pages[location.hash.slice(1)]?location.hash.slice(1):'overview';$('#main').innerHTML='<div class="loading">Loading your research workspace…</div>';await refresh();}
setInterval(()=>{if(!$('#shell').hidden&&!document.hidden){const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);refresh(!editing&&['overview','agents','trading','portfolio'].includes(state.tab)).catch(()=>{});}},4000);
start().catch(e=>{$('#shell').hidden=false;$('#main').innerHTML=`<div class="notice error">${esc(e.message)}. Verify the service is running and reload.</div>`;});
